#include <iostream>
#include <string>

int main() {
    int decimal = 1234;
    std::string hex = "";

    int temp = decimal;
    if (temp == 0) {
        hex = "0";
    } else {
        while (temp != 0) {
            int hexValue = temp % 16;
            char hexChar = (hexValue <= 9 && hexValue >= 0) 
                ? static_cast<char>(hexValue + '0') 
                : static_cast<char>(hexValue - 10 + 'A');
            hex = hexChar + hex;
            temp /= 16;
        }
    }

    std::cout << "Decimal: " << decimal << "\n";
    std::cout << "Hex: " << hex << "\n";
    return 0;
}

#include <iostream>

int main() {
    // Demonstrate break: accumulate until sum >= 100
    int sumBreak = 0;
    int numBreak = 0;
    while (numBreak < 20) {
        numBreak++;
        sumBreak += numBreak;
        if (sumBreak >= 100) {
            break;
        }
    }
    std::cout << "Break - Number: " << numBreak << ", Sum: " << sumBreak << "\n";

    // Demonstrate continue: sum 1 to 20 excluding 10 and 11
    int sumContinue = 0;
    int numContinue = 0;
    while (numContinue < 20) {
        numContinue++;
        if (numContinue == 10 || numContinue == 11) {
            continue;
        }
        sumContinue += numContinue;
    }
    std::cout << "Continue - Sum excluding 10 and 11: " << sumContinue << "\n";

    return 0;
}
